const sb = async (path, method="GET", body=null) => {
  const token = getToken();
  const res = await fetch(`${SB_URL}/rest/v1/${path}`, {
    method,
    headers: { apikey:SB_KEY, Authorization:`Bearer ${token}`, "Content-Type":"application/json", Prefer:"return=representation" },
    body: body ? JSON.stringify(body) : null,
  });
  const text = await res.text();
  if (!res.ok) {
    const err = text ? JSON.parse(text) : {};
    // JWT expired — clear and force re-login
    if (err.message==="JWT expired" || res.status===401) {
      localStorage.removeItem("wf_token");
      localStorage.removeItem("wf_user");
      window.location.reload();
      return [];
    }
    throw new Error(text);
  }
  return text ? JSON.parse(text) : [];
};

const sbAuth = async (endpoint, body) => {
  const res = await fetch(`${SB_URL}/auth/v1/${endpoint}`, {
    method:"POST",
    headers: { apikey:SB_KEY, "Content-Type":"application/json" },
    body: JSON.stringify(body),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description||data.msg||"Auth error");
  return data;
};

