    if(val){await sb("timeline","POST",{work_id:w.id,event:"Delivered",user_id:user.id});tl=[...tl,{event:"Delivered",created_at:new Date().toISOString()}];}
    syncWork({...w,delivered:val,timeline:tl});notify(val?"✓ Delivered!":"Undone");
