function PasswordChanger({T,notify}){
  const[newPass,setNewPass]=useState(""); const[loading,setLoading]=useState(false);
  const inp={background:T.card,border:`1px solid ${T.border}`,borderRadius:10,color:T.text,padding:"10px 13px",fontSize:13,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};
  const change=async()=>{
    if(!newPass||newPass.length<6){notify("Min 6 characters","error");return;}
    setLoading(true);
    try{
      const res=await fetch(`${SB_URL}/auth/v1/user`,{method:"PUT",headers:{apikey:SB_KEY,Authorization:`Bearer ${getToken()}`,"Content-Type":"application/json"},body:JSON.stringify({password:newPass})});
      if(!res.ok)throw new Error("Failed");
      notify("Password changed! ✅");setNewPass("");
    }catch(e){notify("Error: "+e.message,"error");}finally{setLoading(false);}
  };
  return(
    <div style={{display:"flex",gap:8}}>
      <input style={{...inp,flex:1}} type="password" placeholder="New password (min 6 chars)" value={newPass} onChange={e=>setNewPass(e.target.value)}/>
      <button onClick={change} disabled={loading} style={{background:C.accent,color:"#fff",border:"none",borderRadius:10,padding:"10px 16px",fontWeight:700,fontSize:13,opacity:loading?0.7:1}}>{loading?"...":"Change"}</button>
    </div>
  );
}

