// ── Calendar View ─────────────────────────────────────────────────────────────
function CalendarView({T,bp,works,clients,onOpenWork,accentColor}){
  const AC=accentColor||"#6C63FF";
  const [currentDate,setCurrentDate]=useState(new Date());
  const [selectedDay,setSelectedDay]=useState(null);

  const year=currentDate.getFullYear();
  const month=currentDate.getMonth();
  const monthName=currentDate.toLocaleDateString("en-IN",{month:"long",year:"numeric"});
  const firstDay=new Date(year,month,1).getDay();
  const daysInMonth=new Date(year,month+1,0).getDate();
  const DAYS=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];

  const getWorksByDate=(day)=>{
    const dateStr=`${year}-${String(month+1).padStart(2,"0")}-${String(day).padStart(2,"0")}`;
    return works.filter(w=>w.deadline===dateStr);
  };

  const isToday=(day)=>{
    const t=new Date();
    return t.getDate()===day&&t.getMonth()===month&&t.getFullYear()===year;
  };

  const isPast=(day)=>{
    const d=new Date(year,month,day);
    return d<new Date(new Date().setHours(0,0,0,0));
  };

  const selectedWorks=selectedDay?getWorksByDate(selectedDay):[];
  const STATUS_COLOR={"Not Started":"#6B7280","Started":"#38BDF8","In Progress":"#F59E0B","Sent":"#A78BFA","Completed":"#22C55E"};

  return(
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20,flexWrap:"wrap",gap:10}}>
        <h2 style={{color:T.text,fontWeight:800,fontSize:bp.isMobile?18:22,margin:0}}>📅 Deadline Calendar</h2>
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          <button onClick={()=>setCurrentDate(new Date(year,month-1,1))} style={{background:T.surface,border:`1px solid ${T.border}`,color:T.text,borderRadius:8,padding:"7px 12px",cursor:"pointer",fontWeight:700}}>‹</button>
          <span style={{color:T.text,fontWeight:700,fontSize:14,minWidth:140,textAlign:"center"}}>{monthName}</span>
          <button onClick={()=>setCurrentDate(new Date(year,month+1,1))} style={{background:T.surface,border:`1px solid ${T.border}`,color:T.text,borderRadius:8,padding:"7px 12px",cursor:"pointer",fontWeight:700}}>›</button>
          <button onClick={()=>setCurrentDate(new Date())} style={{background:AC,color:"#fff",border:"none",borderRadius:8,padding:"7px 14px",cursor:"pointer",fontWeight:700,fontSize:12}}>Today</button>
        </div>
      </div>

      {/* Legend */}
      <div style={{display:"flex",gap:14,marginBottom:14,flexWrap:"wrap"}}>
        {[["#EF4444","Overdue"],["#F59E0B","Due Today"],[AC,"Has Deadline"],["#22C55E","Completed"]].map(([c,l])=>(
          <div key={l} style={{display:"flex",alignItems:"center",gap:5}}><div style={{width:10,height:10,borderRadius:"50%",background:c}}/><span style={{color:T.muted,fontSize:11}}>{l}</span></div>
        ))}
      </div>

      {/* Calendar Grid */}
      <div style={{background:T.surface,borderRadius:14,padding:bp.isMobile?"12px":"18px",border:`1px solid ${T.border}`,marginBottom:16}}>
        {/* Day headers */}
        <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:4,marginBottom:8}}>
          {DAYS.map(d=><div key={d} style={{color:T.muted,fontSize:11,fontWeight:700,textAlign:"center",padding:"4px 0"}}>{d}</div>)}
        </div>
        {/* Days grid */}
        <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:4}}>
          {Array.from({length:firstDay}).map((_,i)=><div key={`e${i}`}/>)}
          {Array.from({length:daysInMonth}).map((_,i)=>{
            const day=i+1;
            const dayWorks=getWorksByDate(day);
            const today=isToday(day);
            const past=isPast(day);
            const overdueWks=dayWorks.filter(w=>w.status!=="Completed");
            const hasOverdue=past&&overdueWks.length>0;
            const isSelected=selectedDay===day;
            const isTodayDeadline=!past&&dayWorks.length>0;

            return(
              <div key={day} onClick={()=>setSelectedDay(isSelected?null:day)}
                style={{
                  minHeight:bp.isMobile?40:52,borderRadius:8,padding:bp.isMobile?"4px":"6px",cursor:"pointer",
                  background:isSelected?AC+"33":today?AC+"22":T.card,
                  border:`1.5px solid ${isSelected?AC:today?AC:T.border}`,
                  transition:"all 0.15s",position:"relative"
                }}>
                <div style={{color:today?AC:past&&!dayWorks.length?T.muted:T.text,fontWeight:today?800:dayWorks.length?700:400,fontSize:bp.isMobile?11:13,marginBottom:2}}>{day}</div>
                {dayWorks.slice(0,bp.isMobile?1:3).map((w,wi)=>(
                  <div key={w.id} style={{background:hasOverdue?"#EF444444":w.status==="Completed"?"#22C55E33":AC+"33",borderRadius:3,padding:"1px 4px",marginBottom:1,overflow:"hidden"}}>
                    <div style={{color:hasOverdue?"#EF4444":w.status==="Completed"?"#22C55E":AC,fontSize:9,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{w.title}</div>
                  </div>
                ))}
                {dayWorks.length>3&&!bp.isMobile&&<div style={{color:T.muted,fontSize:9}}>+{dayWorks.length-3} more</div>}
                {dayWorks.length>1&&bp.isMobile&&<div style={{color:T.muted,fontSize:9}}>+{dayWorks.length-1}</div>}
                {hasOverdue&&<div style={{position:"absolute",top:3,right:3,width:6,height:6,borderRadius:"50%",background:"#EF4444"}}/>}
              </div>
            );
          })}
        </div>
      </div>

      {/* Selected Day Works */}
      {selectedDay&&(
        <div style={{background:T.surface,borderRadius:14,padding:"16px 18px",border:`1px solid ${T.border}`,marginBottom:16}}>
          <div style={{fontWeight:700,fontSize:14,color:T.text,marginBottom:12}}>
            📋 {selectedDay} {monthName} — {selectedWorks.length===0?"No deadlines":""+selectedWorks.length+" work"+(selectedWorks.length>1?"s":"")}
          </div>
          {selectedWorks.length===0&&<div style={{color:T.muted,fontSize:13}}>No deadlines on this day</div>}
          {selectedWorks.map(w=>{
            const cl=clients.find(c=>c.id===w.client_id);
            const overdue=isPast(selectedDay)&&w.status!=="Completed";
            return(
              <div key={w.id} onClick={()=>onOpenWork(w)} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 0",borderBottom:`1px solid ${T.border}`,cursor:"pointer",gap:8}}>
                <div style={{display:"flex",gap:10,alignItems:"center",minWidth:0}}>
                  <div style={{width:10,height:10,borderRadius:"50%",background:STATUS_COLOR[w.status]||"#6B7280",flexShrink:0}}/>
                  <div style={{minWidth:0}}>
                    <div style={{color:T.text,fontWeight:600,fontSize:13,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{w.title}</div>
                    <div style={{color:T.muted,fontSize:11}}>{cl?.name} · {w.category}</div>
                  </div>
                </div>
                <div style={{display:"flex",gap:8,alignItems:"center",flexShrink:0}}>
                  {overdue&&<span style={{background:"#EF444422",color:"#EF4444",borderRadius:20,padding:"2px 8px",fontSize:10,fontWeight:700}}>Overdue</span>}
                  <span style={{background:STATUS_COLOR[w.status]+"22",color:STATUS_COLOR[w.status],border:`1px solid ${STATUS_COLOR[w.status]}44`,borderRadius:20,padding:"2px 10px",fontSize:11,fontWeight:700}}>{w.status}</span>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Month Summary */}
      <div style={{display:"grid",gridTemplateColumns:bp.isMobile?"repeat(2,1fr)":"repeat(4,1fr)",gap:10}}>
        {[
          {label:"This Month Deadlines",value:works.filter(w=>{const d=new Date(w.deadline);return d.getMonth()===month&&d.getFullYear()===year;}).length,color:AC},
          {label:"Completed",value:works.filter(w=>{const d=new Date(w.deadline);return d.getMonth()===month&&d.getFullYear()===year&&w.status==="Completed";}).length,color:"#22C55E"},
          {label:"Overdue",value:works.filter(w=>w.deadline&&new Date(w.deadline)<new Date()&&w.status!=="Completed").length,color:"#EF4444"},
          {label:"Upcoming",value:works.filter(w=>{const d=new Date(w.deadline);return d>new Date()&&d.getMonth()===month&&d.getFullYear()===year;}).length,color:"#F59E0B"},
        ].map(({label,value,color})=>(
          <div key={label} style={{background:T.surface,borderRadius:12,padding:"14px",border:`1px solid ${T.border}`,textAlign:"center"}}>
            <div style={{color,fontWeight:900,fontSize:22}}>{value}</div>
            <div style={{color:T.muted,fontSize:11,marginTop:3}}>{label}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── Onboarding Flow ───────────────────────────────────────────────────────────
function OnboardingFlow({T,bp,user,onComplete,onAddClient,onAddWork,accentColor}){
  const AC=accentColor||"#6C63FF";
  const [step,setStep]=useState(0);
  const [bizName,setBizName]=useState("");
  const [profession,setProfession]=useState("");
  const [clientName,setClientName]=useState("");
  const [clientPhone,setClientPhone]=useState("");
  const inp={background:T.card,border:`1px solid ${T.border}`,borderRadius:10,color:T.text,padding:"12px 14px",fontSize:14,outline:"none",width:"100%",boxSizing:"border-box",fontFamily:"inherit"};

  const PROFESSIONS=["Video Editor","Graphic Designer","Web Developer","Photographer","Content Creator","Social Media Manager","UI/UX Designer","Motion Designer","Copywriter","Illustrator","Other"];

  const steps=[
    {title:"Welcome to Workflow! 👋",sub:"Let's set up your workspace in 3 quick steps"},
    {title:"About Your Business 🏢",sub:"This helps personalise your invoices and profile"},
    {title:"Add Your First Client 👤",sub:"Who do you work with? Add them now"},
    {title:"You're all set! 🎉",sub:"Your workspace is ready to go"},
  ];

  const progressPct=(step/3)*100;

  return(
    <div style={{minHeight:"100vh",background:T.bg,display:"flex",alignItems:"center",justifyContent:"center",padding:20,fontFamily:"'Inter',system-ui,sans-serif"}}>
      <div style={{width:"100%",maxWidth:480}}>
        {/* Progress bar */}
        <div style={{background:T.card,borderRadius:4,height:4,marginBottom:32,overflow:"hidden"}}>
          <div style={{background:AC,height:"100%",width:`${progressPct}%`,borderRadius:4,transition:"width 0.4s"}}/>
        </div>

        <div style={{background:T.surface,borderRadius:20,padding:bp.isMobile?"24px":"32px",border:`1px solid ${T.border}`}}>
          {/* Step indicator */}
          <div style={{display:"flex",gap:8,marginBottom:24}}>
            {[0,1,2,3].map(i=>(
              <div key={i} style={{flex:1,height:4,borderRadius:2,background:i<=step?AC:T.card,transition:"background 0.3s"}}/>
            ))}
          </div>

          <div style={{textAlign:"center",marginBottom:28}}>
            <div style={{fontSize:48,marginBottom:12}}>
              {step===0?"🚀":step===1?"🏢":step===2?"👤":"🎉"}
            </div>
            <div style={{color:T.text,fontWeight:800,fontSize:bp.isMobile?20:24,marginBottom:8}}>{steps[step].title}</div>
            <div style={{color:T.muted,fontSize:14}}>{steps[step].sub}</div>
          </div>

          {/* Step 0 — Welcome */}
          {step===0&&(
            <div style={{textAlign:"center"}}>
              <div style={{background:T.card,borderRadius:14,padding:"16px 20px",marginBottom:20,textAlign:"left"}}>
                {[["📋","Track all your clients and works"],["📤","Send WhatsApp updates in 1 click"],["🧾","Generate professional invoices"],["📊","See your revenue and analytics"],["📅","Never miss a deadline again"]].map(([icon,text])=>(
                  <div key={text} style={{display:"flex",gap:12,alignItems:"center",padding:"8px 0",borderBottom:`1px solid ${T.border}`}}>
                    <span style={{fontSize:20,flexShrink:0}}>{icon}</span>
                    <span style={{color:T.text,fontSize:13}}>{text}</span>
                  </div>
                ))}
              </div>
              <button onClick={()=>setStep(1)} style={{background:AC,color:"#fff",border:"none",borderRadius:12,padding:"14px 32px",fontWeight:700,fontSize:16,cursor:"pointer",width:"100%"}}>
                Get Started →
              </button>
              <button onClick={onComplete} style={{background:"none",border:"none",color:T.muted,fontSize:12,cursor:"pointer",marginTop:12}}>Skip setup</button>
            </div>
          )}

          {/* Step 1 — Business */}
          {step===1&&(
            <div>
              <div style={{display:"flex",flexDirection:"column",gap:12,marginBottom:24}}>
                <div>
                  <div style={{color:T.muted,fontSize:11,fontWeight:700,marginBottom:5,letterSpacing:"0.06em"}}>YOUR NAME / BUSINESS NAME</div>
                  <input style={inp} placeholder="e.g. Noman Khan Creative" value={bizName} onChange={e=>setBizName(e.target.value)} autoFocus/>
                </div>
                <div>
                  <div style={{color:T.muted,fontSize:11,fontWeight:700,marginBottom:8,letterSpacing:"0.06em"}}>WHAT DO YOU DO?</div>
                  <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8}}>
                    {PROFESSIONS.map(p=>(
                      <button key={p} onClick={()=>setProfession(p)}
                        style={{background:profession===p?AC+"22":T.card,color:profession===p?AC:T.muted,border:`1.5px solid ${profession===p?AC:T.border}`,borderRadius:10,padding:"10px 8px",fontSize:12,fontWeight:600,cursor:"pointer",textAlign:"center"}}>
                        {p}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
                <button onClick={()=>setStep(0)} style={{background:"none",border:`1px solid ${T.border}`,color:T.muted,borderRadius:12,padding:"13px",fontWeight:600,fontSize:14,cursor:"pointer"}}>← Back</button>
                <button onClick={()=>{if(bizName.trim()){lsSet("wf_biz",{name:bizName,tagline:profession});setStep(2);}}} style={{background:AC,color:"#fff",border:"none",borderRadius:12,padding:"13px",fontWeight:700,fontSize:14,cursor:"pointer",opacity:bizName.trim()?1:0.5}}>Next →</button>
              </div>
            </div>
          )}

          {/* Step 2 — First Client */}
          {step===2&&(
            <div>
              <div style={{display:"flex",flexDirection:"column",gap:12,marginBottom:24}}>
                <div>
                  <div style={{color:T.muted,fontSize:11,fontWeight:700,marginBottom:5,letterSpacing:"0.06em"}}>CLIENT NAME *</div>
                  <input style={inp} placeholder="e.g. ABC Company" value={clientName} onChange={e=>setClientName(e.target.value)} autoFocus/>
                </div>
                <div>
                  <div style={{color:T.muted,fontSize:11,fontWeight:700,marginBottom:5,letterSpacing:"0.06em"}}>PHONE NUMBER</div>
                  <input style={inp} placeholder="Client's phone" type="tel" value={clientPhone} onChange={e=>setClientPhone(e.target.value)}/>
                </div>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
                <button onClick={()=>setStep(1)} style={{background:"none",border:`1px solid ${T.border}`,color:T.muted,borderRadius:12,padding:"13px",fontWeight:600,fontSize:14,cursor:"pointer"}}>← Back</button>
                <button onClick={async()=>{
                  if(clientName.trim()){
                    await onAddClient({name:clientName.trim(),phone:clientPhone,email:"",company:"",notes:""});
                  }
                  setStep(3);
                }} style={{background:AC,color:"#fff",border:"none",borderRadius:12,padding:"13px",fontWeight:700,fontSize:14,cursor:"pointer",opacity:clientName.trim()?1:0.5}}>
                  {clientName.trim()?"Add Client →":"Skip →"}
                </button>
              </div>
              {!clientName.trim()&&<div style={{color:T.muted,fontSize:11,textAlign:"center",marginTop:8}}>You can add clients later too</div>}
            </div>
          )}

          {/* Step 3 — Done */}
          {step===3&&(
            <div style={{textAlign:"center"}}>
              <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:10,marginBottom:24}}>
                {[["🎯","Your first client added"],["📋","Ready to create works"],["🧾","Invoices ready to send"],["📊","Analytics tracking started"]].map(([icon,text])=>(
                  <div key={text} style={{background:T.card,borderRadius:12,padding:"14px 10px",textAlign:"center"}}>
                    <div style={{fontSize:24,marginBottom:6}}>{icon}</div>
                    <div style={{color:T.muted,fontSize:11}}>{text}</div>
                  </div>
                ))}
              </div>
              <button onClick={onComplete} style={{background:AC,color:"#fff",border:"none",borderRadius:12,padding:"14px 32px",fontWeight:700,fontSize:16,cursor:"pointer",width:"100%"}}>
                Open Workflow 🚀
              </button>
            </div>
          )}
        </div>

        {/* Step dots */}
        <div style={{display:"flex",justifyContent:"center",gap:8,marginTop:20}}>
          {[0,1,2,3].map(i=>(
            <div key={i} style={{width:i===step?24:8,height:8,borderRadius:4,background:i===step?AC:T.border,transition:"all 0.3s"}}/>
          ))}
        </div>
      </div>
    </div>
  );
}

